/// Marker types naming each stream in `StreamCall<'_, Feed, Marker>`.
pub mod streams {
    /// `v1.algo.order` (algo_order.algo_order).
    #[derive(Debug, Clone, Copy)]
    pub struct AlgoOrderAlgoOrder;
    /// `v1.candle` (candlestick.candlestick).
    #[derive(Debug, Clone, Copy)]
    pub struct CandlestickCandlestick;
    /// `v1.fill` (execution.fill).
    #[derive(Debug, Clone, Copy)]
    pub struct ExecutionFill;
    /// `v1.position` (execution.positions).
    #[derive(Debug, Clone, Copy)]
    pub struct ExecutionPositions;
    /// `v1.cancel` (order.cancel_status).
    #[derive(Debug, Clone, Copy)]
    pub struct OrderCancelStatus;
    /// `v1.order` (order.order).
    #[derive(Debug, Clone, Copy)]
    pub struct OrderOrder;
    /// `v1.state` (order.order_state).
    #[derive(Debug, Clone, Copy)]
    pub struct OrderOrderState;
    /// `v1.book.d` (orderbook.orderbook_delta).
    #[derive(Debug, Clone, Copy)]
    pub struct OrderbookOrderbookDelta;
    /// `v1.book.s` (orderbook.orderbook_snap).
    #[derive(Debug, Clone, Copy)]
    pub struct OrderbookOrderbookSnap;
    /// `v1.quote` (rfq.rfq_quote).
    #[derive(Debug, Clone, Copy)]
    pub struct RfqRfqQuote;
    /// `v1.mini.d` (ticker.mini_ticker_delta).
    #[derive(Debug, Clone, Copy)]
    pub struct TickerMiniTickerDelta;
    /// `v1.mini.s` (ticker.mini_ticker_snap).
    #[derive(Debug, Clone, Copy)]
    pub struct TickerMiniTickerSnap;
    /// `v1.ticker.d` (ticker.ticker_delta).
    #[derive(Debug, Clone, Copy)]
    pub struct TickerTickerDelta;
    /// `v1.ticker.s` (ticker.ticker_snap).
    #[derive(Debug, Clone, Copy)]
    pub struct TickerTickerSnap;
    /// `v1.trade` (trade.trade).
    #[derive(Debug, Clone, Copy)]
    pub struct TradeTrade;
    /// `v1.deposit` (transfer.deposit).
    #[derive(Debug, Clone, Copy)]
    pub struct TransferDeposit;
    /// `v1.transfer` (transfer.transfer).
    #[derive(Debug, Clone, Copy)]
    pub struct TransferTransfer;
    /// `v1.withdrawal` (transfer.withdrawal).
    #[derive(Debug, Clone, Copy)]
    pub struct TransferWithdrawal;
}

