    #[test]
    fn every_stream_is_reachable() {
        let client = crate::Grvt::new(Config::new(Environment::testnet())).unwrap();
        let mut reached = 0;
        let c = client.algo_order_stream().sub_account_id(1);
        assert_eq!(c.spec().stream, "v1.algo.order");
        assert!(!c.selector().is_empty());
        reached += 1;
        let c = client.candlestick_stream().instrument("X");
        assert_eq!(c.spec().stream, "v1.candle");
        assert!(!c.selector().is_empty());
        reached += 1;
        let c = client.fill_stream().sub_account_id(1);
        assert_eq!(c.spec().stream, "v1.fill");
        assert!(!c.selector().is_empty());
        reached += 1;
        let c = client.positions_stream().sub_account_id(1);
        assert_eq!(c.spec().stream, "v1.position");
        assert!(!c.selector().is_empty());
        reached += 1;
        let c = client.cancel_status_stream().sub_account_id(1);
        assert_eq!(c.spec().stream, "v1.cancel");
        assert!(!c.selector().is_empty());
        reached += 1;
        let c = client.order_stream().sub_account_id(1);
        assert_eq!(c.spec().stream, "v1.order");
        assert!(!c.selector().is_empty());
        reached += 1;
        let c = client.order_state_stream().sub_account_id(1);
        assert_eq!(c.spec().stream, "v1.state");
        assert!(!c.selector().is_empty());
        reached += 1;
        let c = client.orderbook_delta_stream().instrument("X");
        assert_eq!(c.spec().stream, "v1.book.d");
        assert!(!c.selector().is_empty());
        reached += 1;
        let c = client.orderbook_snap_stream().instrument("X");
        assert_eq!(c.spec().stream, "v1.book.s");
        assert!(!c.selector().is_empty());
        reached += 1;
        let c = client.rfq_quote_stream().sub_account_id(1);
        assert_eq!(c.spec().stream, "v1.quote");
        assert!(!c.selector().is_empty());
        reached += 1;
        let c = client.mini_ticker_delta_stream().instrument("X");
        assert_eq!(c.spec().stream, "v1.mini.d");
        assert!(!c.selector().is_empty());
        reached += 1;
        let c = client.mini_ticker_snap_stream().instrument("X");
        assert_eq!(c.spec().stream, "v1.mini.s");
        assert!(!c.selector().is_empty());
        reached += 1;
        let c = client.ticker_delta_stream().instrument("X");
        assert_eq!(c.spec().stream, "v1.ticker.d");
        assert!(!c.selector().is_empty());
        reached += 1;
        let c = client.ticker_snap_stream().instrument("X");
        assert_eq!(c.spec().stream, "v1.ticker.s");
        assert!(!c.selector().is_empty());
        reached += 1;
        let c = client.trade_stream().instrument("X");
        assert_eq!(c.spec().stream, "v1.trade");
        assert!(!c.selector().is_empty());
        reached += 1;
        let c = client.deposit_stream().main_account_id("X");
        assert_eq!(c.spec().stream, "v1.deposit");
        assert!(!c.selector().is_empty());
        reached += 1;
        let c = client.transfer_stream().main_account_id("X");
        assert_eq!(c.spec().stream, "v1.transfer");
        assert!(!c.selector().is_empty());
        reached += 1;
        let c = client.withdrawal_stream().main_account_id("X");
        assert_eq!(c.spec().stream, "v1.withdrawal");
        assert!(!c.selector().is_empty());
        reached += 1;
        assert_eq!(reached, specs::STREAMS.len());
    }
